.lg-toolbar-separator{display:block;height:16px;width:1px;background:currentColor;opacity:.16;margin:0 3px;flex-shrink:0}
.lg-switch:focus-visible,.lg-button button:focus-visible,.lg-segmented button:focus-visible,.lg-chip button:focus-visible,.lg-toolbar button:focus-visible{outline:2px solid var(--lg-focus,#647a99);outline-offset:3px}
.lg-button:has(button:focus-visible),.lg-chip:has(button:focus-visible),.lg-toolbar:has(button:focus-visible),.lg-segmented:has(button:focus-visible){outline:none}
@media(pointer:coarse){.lg-button button{min-height:42px}.lg-button[data-size=icon] button{width:42px;height:42px}.lg-chip button{min-height:40px}.lg-segmented button{height:38px}.lg-toolbar button{height:38px;width:38px}}
@media(forced-colors:active){.lg-switch-track{background:Canvas!important;border:1px solid ButtonText}.lg-switch[aria-checked=true] .lg-switch-track{background:Highlight!important}.lg-range-fill{background:Highlight}.lg-range-track{background:GrayText}.lg-segmented button[aria-checked=true],.lg-chip button[aria-pressed=true],.lg-toolbar button[aria-pressed=true]{outline:1px solid Highlight}.lg-button[data-variant=accent]{color:ButtonText}}

/* Opt out per instance, not globally: actual controls retain keyboard focus. */
.lg[data-focus-ring="none"]:focus,
.lg[data-focus-ring="none"]:focus-visible,
.lg[data-focus-ring="none"]:has(:focus-visible) {outline:none!important;}
